package cn.zhe.chaojibeauty;

import android.graphics.RenderEffect;
import android.graphics.RuntimeShader;

/** Uses the G2 distance function generated by the installed launcher for material type 4 (Dock). */
final class DockMaterial {
    private final RuntimeShader shader;

    DockMaterial(ClassLoader launcher) throws ReflectiveOperationException {
        shader = GlassShader.compile(launcher, "a", PARAMETERS + SMOOTH_DISTANCE + OPTICS);
    }

    // Matches Canvas.drawRoundRect in the launcher's indicator fallback.
    DockMaterial() {
        shader = new RuntimeShader("uniform shader uniBDFBitmap;" + PARAMETERS +
                "float distanceToEdge(float2 p){float2 q=abs(p)-dockHalf+dockCorner.x;" +
                "return length(max(q,0.))+min(max(q.x,q.y),0.)-dockCorner.x;}" + OPTICS);
    }

    RenderEffect resize(int width, int height, float radius, float weight, float density, boolean dark) {
        shader.setFloatUniform("darkAppearance",dark ? 1f : 0f);
        float band = Math.min(18f * density, height * .34f);
        shader.setFloatUniform("dockHalf", width * .5f, height * .5f);
        shader.setFloatUniform("dockCorner", Math.min(radius, Math.min(width,height) * .5f), weight);
        shader.setFloatUniform("dockOptics", band, band * .86f, 1.3f * density);
        return RenderEffect.createRuntimeShaderEffect(shader, GlassShader.INPUT);
    }

    // Refraction profile and directional highlight adapted from AndroidLiquidGlass (Apache-2.0).
    private static final String PARAMETERS =
            GlassAppearance.DOCK_TONE + "uniform float2 dockHalf; uniform float2 dockCorner; uniform float3 dockOptics;";
    private static final String SMOOTH_DISTANCE =
            "float distanceToEdge(float2 p){return smoothSDF_D(p,dockHalf,dockCorner.x,dockCorner.y);}";
    private static final String OPTICS =
            "half peak(half3 c){return max(c.r,max(c.g,c.b));}" +
            "half4 main(float2 position){" +
            "float2 p=position-dockHalf; float d=distanceToEdge(p);" +
            "float coverage=1.-smoothstep(-1.5,0.,d); if(coverage<=0.)return half4(0);" +
            "float t=clamp(1.+d/dockOptics.x,0.,1.);" +
            "float2 n=float2(distanceToEdge(p+float2(1,0))-distanceToEdge(p-float2(1,0))," +
            "distanceToEdge(p+float2(0,1))-distanceToEdge(p-float2(0,1)));" +
            "n/=max(.0001,length(n));" +
            "float shift=dockOptics.y*(1.-sqrt(max(0.,1.-t*t)));" +
            "float2 q=clamp(position-n*shift,float2(.5),2.*dockHalf-.5);" +
            "half3 color=uniBDFBitmap.eval(q).rgb;" +
            "float rim=1.-smoothstep(.0,dockOptics.z,-d);" +
            "float light=pow(abs(dot(n,float2(-.6,-.8))),2.2);" +
            "half shine=.025+rim*(.12+.65*light); half3 tint=half3(.98,.99,1.);" +
            // A private display can present a black clear before the wallpaper reappears.
            // Let the desktop show through while keeping the same premultiplied glass highlight.
            "if(peak(color)<=.012){" +
            "  half signal=max(peak(uniBDFBitmap.eval(dockHalf).rgb)," +
            "                  max(peak(uniBDFBitmap.eval(dockHalf*float2(.4,.6)).rgb)," +
            "                      peak(uniBDFBitmap.eval(dockHalf*float2(1.6,1.4)).rgb)));" +
            "  if(signal<=.012) return half4(tint*shine*coverage,shine*coverage);" +
            "}" +
            "color=mix(dockTone(color),tint,shine);" +
            "return half4(color*coverage,coverage);}";
}
